import { GoogleGenAI, Type } from "@google/genai";
import { GEO_AGENT_SYSTEM_INSTRUCTION } from '../constants';
import { AuditData, FormInput } from '../types';

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const runAudit = async (input: FormInput): Promise<AuditData> => {
  const systemInstructionText = JSON.stringify(GEO_AGENT_SYSTEM_INSTRUCTION);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Proszę o audyt dla: Nazwa Firmy: ${input.companyName}, Miasto: ${input.city}, Adres WWW: ${input.website}.

      WAŻNE: Wykonaj 'step_1_grounding_research' używając Google Search aby znaleźć realne dane o firmie.
      Następnie wygeneruj raporty zgodnie z instrukcją systemową.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: systemInstructionText,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            companyName: { type: Type.STRING },
            overallScore: { type: Type.NUMBER, description: "AI Visibility Score (0-100)" },
            executiveSummary: { type: Type.STRING, description: "Krótkie podsumowanie menadżerskie" },
            spiderChartData: {
              type: Type.ARRAY,
              description: "Dane do wykresu pajęczynowego dla 7 Filarów Optymalizacji",
              items: {
                type: Type.OBJECT,
                properties: {
                  subject: { type: Type.STRING, description: "Nazwa filaru, np. Schema, E-E-A-T" },
                  score: { type: Type.NUMBER, description: "Wynik 0-100" },
                  fullMark: { type: Type.NUMBER, description: "Zawsze 100" }
                }
              }
            },
            mainReportSections: {
              type: Type.ARRAY,
              description: "Sekcje raportu głównego (Main Board)",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Treść w formacie Markdown" }
                }
              }
            },
            technicalReportSections: {
              type: Type.ARRAY,
              description: "Sekcje raportu technicznego",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Treść w formacie Markdown, włączając kod JSON-LD/HTML" }
                }
              }
            },
            salesTeaserSections: {
              type: Type.ARRAY,
              description: "Sekcje trailera sprzedażowego",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Perswazyjna treść Markdown" }
                }
              }
            }
          },
          required: [
            "companyName", 
            "overallScore", 
            "executiveSummary", 
            "spiderChartData", 
            "mainReportSections", 
            "technicalReportSections", 
            "salesTeaserSections"
          ]
        }
      }
    });

    if (response.text) {
      const data = JSON.parse(response.text) as AuditData;
      return data;
    } else {
      throw new Error("No data returned from Gemini");
    }

  } catch (error) {
    console.error("Audit failed", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { FormInput } from '../types';

interface AuditFormProps {
  onSubmit: (data: FormInput) => void;
  isLoading: boolean;
}

const AuditForm: React.FC<AuditFormProps> = ({ onSubmit, isLoading }) => {
  const [formData, setFormData] = useState<FormInput>({
    companyName: '',
    city: '',
    website: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit(formData);
  };

  return (
    <div className="w-full max-w-lg mx-auto bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700">
      <div className="mb-8 text-center">
        <h2 className="text-2xl font-bold text-white mb-2">Rozpocznij Audyt GEO</h2>
        <p className="text-slate-400">Sprawdź jak AI widzi Twoją firmę.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-1">Nazwa Firmy</label>
          <input
            type="text"
            required
            className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
            placeholder="np. Pizzeria Napoli"
            value={formData.companyName}
            onChange={(e) => setFormData(prev => ({ ...prev, companyName: e.target.value }))}
            disabled={isLoading}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-1">Miasto</label>
          <input
            type="text"
            required
            className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
            placeholder="np. Warszawa"
            value={formData.city}
            onChange={(e) => setFormData(prev => ({ ...prev, city: e.target.value }))}
            disabled={isLoading}
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-1">Adres WWW</label>
          <input
            type="text" // using text instead of url to allow partial inputs if needed, but validation is better
            required
            className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
            placeholder="np. pizzerianapoli.pl"
            value={formData.website}
            onChange={(e) => setFormData(prev => ({ ...prev, website: e.target.value }))}
            disabled={isLoading}
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className={`w-full py-4 rounded-lg font-bold text-lg shadow-lg transition-all duration-300 transform hover:scale-[1.02] ${
            isLoading 
              ? 'bg-indigo-900 text-indigo-300 cursor-not-allowed' 
              : 'bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-400 hover:to-purple-500 text-white'
          }`}
        >
          {isLoading ? (
            <span className="flex items-center justify-center gap-2">
              <svg className="animate-spin h-5 w-5 text-indigo-300" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Analiza w toku...
            </span>
          ) : (
            'Generuj Raport'
          )}
        </button>
      </form>
    </div>
  );
