// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const runAudit = async (input: FormInput): Promise<AuditData> => {
  const systemInstructionText = JSON.stringify(GEO_AGENT_SYSTEM_INSTRUCTION);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `Wykonaj audyt GEO dla firmy:
      - Nazwa: ${input.companyName}
      - Miasto: ${input.city}
      - URL: ${input.website}

      ZASADY:
      1. Użyj Google Search, aby zweryfikować NAP i opinie.
      2. Wygeneruj JSON zgodny ze schematem.
      3. BĄDŹ ZWIĘZŁY (max 2-3 akapity na sekcję), aby uniknąć ucięcia tekstu (truncation).
      4. Nie powtarzaj tych samych informacji w różnych sekcjach raportu.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: systemInstructionText,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 4000 }, // Allocate budget for better planning and structure
        maxOutputTokens: 8192, // Use maximum available output tokens for this model
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            companyName: { type: Type.STRING },
            overallScore: { type: Type.NUMBER, description: "AI Visibility Score (0-100)" },
            executiveSummary: { type: Type.STRING, description: "Krótkie podsumowanie menadżerskie (max 100 słów)" },
            spiderChartData: {
              type: Type.ARRAY,
              description: "Dane do wykresu pajęczynowego dla 7 Filarów Optymalizacji",
              items: {
                type: Type.OBJECT,
                properties: {
                  subject: { type: Type.STRING, description: "Nazwa filaru, np. Schema, E-E-A-T" },
                  score: { type: Type.NUMBER, description: "Wynik 0-100" },
                  fullMark: { type: Type.NUMBER, description: "Zawsze 100" }
                },
                required: ["subject", "score", "fullMark"]
              }
            },
            mainReportSections: {
              type: Type.ARRAY,
              description: "Sekcje raportu głównego (Main Board)",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Treść Markdown (zwięzła)" }
                },
                required: ["title", "content"]
              }
            },
            technicalReportSections: {
              type: Type.ARRAY,
              description: "Sekcje raportu technicznego",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Treść Markdown z kodem (zwięzła)" }
                },
                required: ["title", "content"]
              }
            },
            salesTeaserSections: {
              type: Type.ARRAY,
              description: "Sekcje trailera sprzedażowego",
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING, description: "Perswazyjna treść Markdown (bardzo krótka)" }
                },
                required: ["title", "content"]
              }
            }
          },
          required: [
            "companyName", 
            "overallScore", 
            "executiveSummary", 
            "spiderChartData", 
            "mainReportSections", 
            "technicalReportSections", 
            "salesTeaserSections"
          ]
        }
      }
    });

    const text = response.text;
    if (text) {
      try {
        return JSON.parse(text) as AuditData;
      } catch (parseError) {
        console.error("Malformed JSON received:", text);
        throw new Error("Otrzymano niekompletne dane z modelu (JSON truncated). Spróbuj ponownie lub podaj krótszą nazwę firmy.");
      }
    } else {
      throw new Error("Model nie zwrócił treści.");
    }

  } catch (error) {
    console.error("Audit failed", error);
    throw error;
  }
};

