import React, { useState, useMemo } from 'react';
import { Competitor } from '../types';

interface CompetitorSelectorProps {
  competitors: Competitor[];
  onConfirm: (selected: Competitor[]) => void;
  isLoading: boolean;
}

const CompetitorSelector: React.FC<CompetitorSelectorProps> = ({ competitors, onConfirm, isLoading }) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [typeFilter, setTypeFilter] = useState<string>('');
  const [scoreFilter, setScoreFilter] = useState<number>(0);

  const businessTypes = useMemo(() => 
    Array.from(new Set(competitors.map(c => c.businessType))),
    [competitors]
  );

  const filteredCompetitors = useMemo(() => {
    return competitors.filter(c => {
      const matchesType = typeFilter === '' || c.businessType === typeFilter;
      const matchesScore = c.estimatedScore >= scoreFilter;
      return matchesType && matchesScore;
    });
  }, [competitors, typeFilter, scoreFilter]);

  const toggleSelection = (id: string) => {
    setSelectedIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= 3) return prev; // Max 3
      return [...prev, id];
    });
  };

  const handleConfirm = () => {
    const selected = competitors.filter(c => selectedIds.includes(c.id));
    onConfirm(selected);
  };

  return (
    <div className="w-full max-w-4xl mx-auto bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl animate-fade-in-up">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-white mb-2">Wybierz Konkurentów do Porównania</h2>
        <p className="text-slate-400">Wybierz dokładnie 3 firmy, które AI ma przeanalizować w Twoim raporcie.</p>
      </div>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
        <div>
          <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-2">Typ Działalności</label>
          <select 
            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2 text-white outline-none focus:ring-2 focus:ring-indigo-500"
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
          >
            <option value="">Wszystkie typy</option>
            {businessTypes.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-2">Minimalny Wynik AI: {scoreFilter}%</label>
          <input 
            type="range" 
            min="0" 
            max="100" 
            value={scoreFilter} 
            onChange={(e) => setScoreFilter(parseInt(e.target.value))}
            className="w-full accent-indigo-500"
          />
        </div>
      </div>

      {/* List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8 max-h-[400px] overflow-y-auto p-2 custom-scrollbar">
        {filteredCompetitors.map(c => {
          const isSelected = selectedIds.includes(c.id);
          const isDisabled = !isSelected && selectedIds.length >= 3;

          return (
            <div 
              key={c.id}
              onClick={() => !isDisabled && toggleSelection(c.id)}
              className={`p-4 rounded-xl border-2 transition-all cursor-pointer ${
                isSelected 
                  ? 'bg-indigo-900/40 border-indigo-500 shadow-lg shadow-indigo-500/10' 
                  : isDisabled 
                    ? 'bg-slate-800/50 border-slate-700 opacity-50 cursor-not-allowed'
                    : 'bg-slate-900 border-slate-700 hover:border-slate-500'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className="text-xs font-bold text-indigo-400 bg-indigo-900/50 px-2 py-0.5 rounded">{c.businessType}</span>
                {isSelected && <span className="text-indigo-400">✅</span>}
              </div>
              <h4 className="text-white font-bold mb-1 truncate">{c.name}</h4>
              <div className="flex items-center gap-2">
                <div className="flex-grow h-1.5 bg-slate-700 rounded-full overflow-hidden">
                  <div className="h-full bg-indigo-500" style={{ width: `${c.estimatedScore}%` }} />
                </div>
                <span className="text-xs text-slate-400 font-mono">{c.estimatedScore}%</span>
              </div>
            </div>
          );
        })}
        {filteredCompetitors.length === 0 && (
          <div className="col-span-full py-12 text-center text-slate-500 border-2 border-dashed border-slate-700 rounded-xl">
            Brak wyników spełniających kryteria.
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-4 border-t border-slate-700 pt-6">
        <div className="text-slate-300">
          Wybrano: <span className="font-bold text-indigo-400">{selectedIds.length}/3</span>
        </div>
        <button
          onClick={handleConfirm}
          disabled={selectedIds.length !== 3 || isLoading}
          className={`px-8 py-3 rounded-lg font-bold transition-all shadow-lg ${
            selectedIds.length === 3 && !isLoading
              ? 'bg-indigo-500 hover:bg-indigo-400 text-white'
              : 'bg-slate-700 text-slate-500 cursor-not-allowed'
          }`}
        >
          {isLoading ? 'Analizowanie...' : 'Generuj Raport Główny'}
        </button>
      </div>
    </div>
  );
};

