import React, { useState } from 'react';
import { AuditData, FormInput, AppState, Competitor } from './types';
import { fetchCompetitors, runFinalAudit } from './services/geminiService';
import AuditForm from './components/AuditForm';
import CompetitorSelector from './components/CompetitorSelector';
import ResultsDashboard from './components/ResultsDashboard';

const App = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [formInput, setFormInput] = useState<FormInput | null>(null);
  const [competitors, setCompetitors] = useState<Competitor[]>([]);
  const [auditData, setAuditData] = useState<AuditData | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleInitialSubmit = async (input: FormInput) => {
    setFormInput(input);
    setAppState(AppState.FETCHING_COMPETITORS);
    setErrorMsg(null);
    try {
      const list = await fetchCompetitors(input);
      setCompetitors(list);
      setAppState(AppState.SELECTING_COMPETITORS);
    } catch (err: any) {
      console.error(err);
      setErrorMsg("Nie udało się pobrać listy konkurentów. Spróbuj ponownie.");
      setAppState(AppState.ERROR);
    }
  };

  const handleCompetitorConfirm = async (selected: Competitor[]) => {
    if (!formInput) return;
    setAppState(AppState.GENERATING_REPORT);
    setErrorMsg(null);
    try {
      const result = await runFinalAudit(formInput, selected);
      setAuditData(result);
      setAppState(AppState.SUCCESS);
    } catch (err: any) {
      console.error(err);
      setErrorMsg("Wystąpił błąd podczas generowania raportu głównego. Spróbuj ponownie.");
      setAppState(AppState.ERROR);
    }
  };

  const handleReset = () => {
    setAuditData(null);
    setCompetitors([]);
    setFormInput(null);
    setAppState(AppState.IDLE);
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-100 flex flex-col font-sans overflow-x-hidden">
      <header className="border-b border-slate-800 bg-slate-900/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2 cursor-pointer" onClick={handleReset}>
            <div className="h-8 w-8 bg-gradient-to-tr from-indigo-500 to-purple-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <span className="font-bold text-white text-lg">G</span>
            </div>
            <span className="font-bold text-xl tracking-tight text-white">GEO Audit Pro</span>
          </div>
          <div className="text-xs font-medium px-3 py-1 bg-slate-800 rounded-full text-indigo-400 border border-slate-700">
            Powered by Gemini 3.0 Pro
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 md:p-8 flex items-center justify-center">
        {appState === AppState.IDLE && (
          <div className="w-full flex flex-col items-center animate-fade-in-up">
            <div className="mb-12 text-center max-w-2xl">
              <h1 className="text-4xl md:text-6xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 to-purple-400 mb-6">
                Widoczność w erze AI
              </h1>
              <p className="text-lg text-slate-400 leading-relaxed">
                Sprawdź, jak Twoja firma jest oceniana przez LLMy i porównaj się z konkurencją w Twoim mieście.
              </p>
            </div>
            <AuditForm onSubmit={handleInitialSubmit} isLoading={false} />
          </div>
        )}

        {appState === AppState.FETCHING_COMPETITORS && (
          <div className="w-full flex flex-col items-center">
             <div className="mb-12 text-center max-w-2xl animate-pulse">
              <h1 className="text-3xl font-bold text-slate-500 mb-4">
                Wyszukiwanie Konkurentów...
              </h1>
              <p className="text-slate-500">
                Przeszukujemy sieć w poszukiwaniu firm z Twojej branży w lokalizacji {formInput?.city}.
              </p>
            </div>
            <div className="w-full max-w-lg bg-slate-800 h-64 rounded-2xl animate-pulse border border-slate-700" />
          </div>
        )}

        {appState === AppState.SELECTING_COMPETITORS && (
          <CompetitorSelector 
            competitors={competitors} 
            onConfirm={handleCompetitorConfirm} 
            isLoading={false}
          />
        )}

        {appState === AppState.GENERATING_REPORT && (
          <div className="w-full flex flex-col items-center">
             <div className="mb-12 text-center max-w-2xl animate-pulse">
              <h1 className="text-3xl font-bold text-slate-500 mb-4">
                Generowanie Raportu GEO...
              </h1>
              <p className="text-slate-500">
                To może potrwać do minuty. Analizujemy E-E-A-T, Schema i porównujemy Cię z wybranymi firmami.
              </p>
            </div>
            <div className="w-full max-w-2xl bg-slate-800 h-96 rounded-2xl animate-pulse border border-slate-700" />
          </div>
        )}

        {appState === AppState.SUCCESS && auditData && (
          <ResultsDashboard data={auditData} onReset={handleReset} />
        )}

        {appState === AppState.ERROR && (
          <div className="text-center max-w-md bg-red-900/20 border border-red-800 p-8 rounded-2xl">
            <div className="text-4xl mb-4">⚠️</div>
            <h3 className="text-xl font-bold text-red-400 mb-2">Błąd</h3>
            <p className="text-red-200 mb-6">{errorMsg}</p>
            <button 
              onClick={handleReset}
              className="px-6 py-2 bg-red-700 hover:bg-red-600 text-white rounded-lg transition-colors"
            >
              Zacznij od nowa
            </button>
          </div>
        )}
      </main>

      <footer className="border-t border-slate-800 py-6 text-center text-slate-500 text-sm bg-slate-900">
        <p>© 2024 GEO Audit Pro Agent. AI Visibility Solutions.</p>
      </footer>

      <style>{`
        @keyframes fade-in-up {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fade-in-up {
          animation: fade-in-up 0.6s ease-out forwards;
        }
        @keyframes fade-in {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        .animate-fade-in {
          animation: fade-in 0.5s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #334155;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #475569;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Competitor } from '../types';

interface CompetitorSelectorProps {
  competitors: Competitor[];
  onConfirm: (selected: Competitor[]) => void;
  isLoading: boolean;
}

const CompetitorSelector: React.FC<CompetitorSelectorProps> = ({ competitors, onConfirm, isLoading }) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [typeFilter, setTypeFilter] = useState<string>('');
  const [scoreFilter, setScoreFilter] = useState<number>(0);

  const businessTypes = useMemo(() => 
    Array.from(new Set(competitors.map(c => c.businessType))),
    [competitors]
  );

  const filteredCompetitors = useMemo(() => {
    return competitors.filter(c => {
      const matchesType = typeFilter === '' || c.businessType === typeFilter;
      const matchesScore = c.estimatedScore >= scoreFilter;
      return matchesType && matchesScore;
    });
  }, [competitors, typeFilter, scoreFilter]);

  const toggleSelection = (id: string) => {
    setSelectedIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= 3) return prev; // Max 3
      return [...prev, id];
    });
  };

  const handleConfirm = () => {
    const selected = competitors.filter(c => selectedIds.includes(c.id));
    onConfirm(selected);
  };

  const progressPercentage = (selectedIds.length / 3) * 100;

  return (
    <div className="w-full max-w-4xl mx-auto bg-slate-800 p-8 rounded-2xl border border-slate-700 shadow-2xl animate-fade-in-up">
      <div className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Wybierz Konkurentów do Porównania</h2>
          <p className="text-slate-400">Wybierz dokładnie 3 firmy, które AI ma przeanalizować w Twoim raporcie.</p>
        </div>

        {/* Visual Progress Indicator in Header */}
        <div className="flex flex-col items-end min-w-[140px]">
          <div className="flex justify-between w-full mb-1">
            <span className="text-xs font-semibold text-slate-400 uppercase">Krok 2/3: Wybór</span>
            <span className="text-xs font-bold text-indigo-400">{selectedIds.length}/3</span>
          </div>
          <div className="w-full h-2 bg-slate-900 rounded-full overflow-hidden border border-slate-700">
            <div 
              className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 transition-all duration-500 ease-out" 
              style={{ width: `${progressPercentage}%` }}
            />
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8 bg-slate-900/40 p-4 rounded-xl border border-slate-700/50">
        <div>
          <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-2">Typ Działalności</label>
          <select 
            className="w-full bg-slate-900 border border-slate-700 rounded-lg px-4 py-2.5 text-white outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
          >
            <option value="">Wszystkie typy</option>
            {businessTypes.map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-2 flex justify-between">
            <span>Minimalny Wynik AI</span>
            <span className="text-indigo-400 font-bold">{scoreFilter}%</span>
          </label>
          <div className="flex items-center gap-4">
            <input 
              type="range" 
              min="0" 
              max="100" 
              value={scoreFilter} 
              onChange={(e) => setScoreFilter(parseInt(e.target.value))}
              className="flex-grow h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
          </div>
        </div>
      </div>

      {/* List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8 max-h-[420px] overflow-y-auto p-2 custom-scrollbar">
        {filteredCompetitors.map(c => {
          const isSelected = selectedIds.includes(c.id);
          const isDisabled = !isSelected && selectedIds.length >= 3;

          return (
            <div 
              key={c.id}
              onClick={() => !isDisabled && toggleSelection(c.id)}
              className={`p-4 rounded-xl border-2 transition-all cursor-pointer relative group ${
                isSelected 
                  ? 'bg-indigo-900/30 border-indigo-500 shadow-lg shadow-indigo-500/10' 
                  : isDisabled 
                    ? 'bg-slate-800/50 border-slate-700 opacity-50 cursor-not-allowed'
                    : 'bg-slate-900 border-slate-700 hover:border-slate-500 hover:bg-slate-800/50'
              }`}
            >
              {isSelected && (
                <div className="absolute -top-2 -right-2 bg-indigo-500 text-white rounded-full p-1 shadow-lg z-10">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                </div>
              )}
              <div className="flex justify-between items-start mb-2">
                <span className="text-[10px] font-bold text-indigo-300 bg-indigo-900/50 px-2 py-0.5 rounded uppercase tracking-tighter truncate max-w-[100px]">{c.businessType}</span>
                <span className={`text-xs font-mono ${isSelected ? 'text-indigo-300' : 'text-slate-500'}`}>{c.estimatedScore}%</span>
              </div>
              <h4 className="text-white font-bold mb-3 truncate leading-tight">{c.name}</h4>
              <div className="w-full h-1 bg-slate-800 rounded-full overflow-hidden">
                <div 
                  className={`h-full transition-all duration-1000 ${isSelected ? 'bg-indigo-400' : 'bg-slate-600'}`} 
                  style={{ width: `${c.estimatedScore}%` }} 
                />
              </div>
            </div>
          );
        })}
        {filteredCompetitors.length === 0 && (
          <div className="col-span-full py-16 text-center text-slate-500 border-2 border-dashed border-slate-700 rounded-xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 mx-auto mb-3 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            Brak wyników spełniających kryteria.
          </div>
        )}
      </div>

      {/* Footer */}
      <div className="flex flex-col md:flex-row items-center justify-between gap-6 border-t border-slate-700 pt-6">
        <div className="flex items-center gap-4 w-full md:w-auto">
          <div className="text-slate-300 text-sm whitespace-nowrap">
            Status: <span className={`font-bold ${selectedIds.length === 3 ? 'text-green-400' : 'text-indigo-400'}`}>
              {selectedIds.length === 3 ? 'Gotowy do analizy' : `Wybierz jeszcze ${3 - selectedIds.length}`}
            </span>
          </div>
          {/* Circular progress alternative for mobile/compact view */}
          <div className="relative h-10 w-10 flex items-center justify-center md:hidden">
            <svg className="h-full w-full transform -rotate-90" viewBox="0 0 36 36">
              <circle cx="18" cy="18" r="16" fill="none" stroke="#1e293b" strokeWidth="4" />
              <circle 
                cx="18" cy="18" r="16" fill="none" stroke="#6366f1" strokeWidth="4" 
                strokeDasharray={`${progressPercentage}, 100`} strokeLinecap="round"
              />
            </svg>
            <span className="absolute text-[10px] font-bold text-white">{selectedIds.length}/3</span>
          </div>
        </div>

        <button
          onClick={handleConfirm}
          disabled={selectedIds.length !== 3 || isLoading}
          className={`w-full md:w-auto px-10 py-4 rounded-xl font-bold transition-all shadow-xl transform active:scale-95 ${
            selectedIds.length === 3 && !isLoading
              ? 'bg-gradient-to-r from-indigo-600 to-indigo-500 hover:from-indigo-500 hover:to-indigo-400 text-white shadow-indigo-500/20'
              : 'bg-slate-700 text-slate-500 cursor-not-allowed border border-slate-600'
          }`}
        >
          {isLoading ? (
            <span className="flex items-center justify-center gap-2">
              <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              Przetwarzanie...
            </span>
          ) : 'Generuj Raport Główny'}
        </button>
      </div>
