import React, { useState } from 'react';
import { AuditData, ReportSection } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, BarChart, Bar, XAxis, YAxis, Tooltip, Cell } from 'recharts';
import { jsPDF } from 'jspdf';

interface ResultsDashboardProps {
  data: AuditData;
  onReset: () => void;
}

const SimpleMarkdown = ({ text }: { text: string }) => {
  const parts = text.split(/(\*\*.*?\*\*)/g);
  return (
    <div className="whitespace-pre-wrap text-slate-300 leading-relaxed">
      {parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          return <strong key={i} className="text-white font-semibold text-indigo-200">{part.slice(2, -2)}</strong>;
        }
        return <span key={i}>{part}</span>;
      })}
    </div>
  );
};

const SectionCard: React.FC<{ section: ReportSection }> = ({ section }) => (
  <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 hover:border-indigo-500/30 transition-colors mb-6 shadow-md">
    <h3 className="text-xl font-bold text-white mb-4 border-b border-slate-700 pb-2">{section.title}</h3>
    <SimpleMarkdown text={section.content} />
  </div>
);

const ResultsDashboard: React.FC<ResultsDashboardProps> = ({ data, onReset }) => {
  const [activeTab, setActiveTab] = useState<'main' | 'tech' | 'sales'>('main');

  const getScoreColor = (score: number) => {
    if (score >= 80) return '#4ade80'; // Green
    if (score >= 50) return '#facc15'; // Yellow
    return '#f87171'; // Red
  };

  const comparisonData = [
    { name: 'Ty', score: data.overallScore },
    ...(data.competitorComparison?.map(c => ({ name: c.competitorName, score: c.score })) || [])
  ];

  const generatePDF = (type: 'main' | 'tech' | 'sales') => {
    const doc = new jsPDF();
    const margin = 20;
    let yPos = 20;

    const addText = (text: string, size: number = 10, isBold: boolean = false, color: [number, number, number] = [0, 0, 0]) => {
      doc.setFontSize(size);
      doc.setFont('helvetica', isBold ? 'bold' : 'normal');
      doc.setTextColor(color[0], color[1], color[2]);

      const lines = doc.splitTextToSize(text.replace(/\*\*/g, ''), 170);
      lines.forEach((line: string) => {
        if (yPos > 280) {
          doc.addPage();
          yPos = 20;
        }
        doc.text(line, margin, yPos);
        yPos += size * 0.5 + 2;
      });
      yPos += 2;
    };

    // Branding Header
    doc.setFillColor(15, 23, 42); // Slate 900
    doc.rect(0, 0, 210, 40, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(22);
    doc.text('GEO Audit Pro Agent', margin, 25);
    doc.setFontSize(10);
    doc.text(`Data audytu: ${new Date().toLocaleDateString('pl-PL')}`, 140, 25);
    yPos = 55;

    // Report Title & Meta
    const titles = {
      main: 'Raport Strategiczny GEO',
      tech: 'Audyt Techniczny SEO (AI Readiness)',
      sales: 'GEO Sales Teaser'
    };

    addText(titles[type], 18, true, [79, 70, 229]); // Indigo 600
    addText(`Firma: ${data.companyName}`, 14, true);
    addText(`AI Visibility Score: ${data.overallScore}/100`, 12, true, [31, 41, 55]);
    yPos += 5;

    if (type === 'main') {
      addText('Podsumowanie Wykonawcze', 14, true);
      addText(data.executiveSummary);
      yPos += 5;

      data.mainReportSections.forEach(section => {
        addText(section.title, 12, true, [79, 70, 229]);
        addText(section.content);
        yPos += 5;
      });

      if (data.competitorComparison) {
        addText('Analiza Konkurencji', 14, true);
        data.competitorComparison.forEach(comp => {
          addText(`${comp.competitorName}: ${comp.score}%`, 11, true);
          addText(comp.keyDifference);
        });
      }
    } else if (type === 'tech') {
      data.technicalReportSections.forEach(section => {
        addText(section.title, 12, true, [37, 99, 235]); // Blue 600
        addText(section.content);
        yPos += 5;
      });
