import React, { useState } from 'react';
import { AuditData, ReportSection } from '../types';
import { ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, BarChart, Bar, XAxis, YAxis, Tooltip, Cell } from 'recharts';
import { jsPDF } from 'jspdf';

interface ResultsDashboardProps {
  data: AuditData;
  onReset: () => void;
}

const SimpleMarkdown = ({ text }: { text: string }) => {
  const parts = text.split(/(\*\*.*?\*\*)/g);
  return (
    <div className="whitespace-pre-wrap text-slate-300 leading-relaxed">
      {parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          return <strong key={i} className="text-white font-semibold text-indigo-200">{part.slice(2, -2)}</strong>;
        }
        return <span key={i}>{part}</span>;
      })}
    </div>
  );
};

const SectionCard: React.FC<{ section: ReportSection }> = ({ section }) => (
  <div className="bg-slate-800 rounded-xl p-6 border border-slate-700 hover:border-indigo-500/30 transition-colors mb-6 shadow-md">
    <h3 className="text-xl font-bold text-white mb-4 border-b border-slate-700 pb-2">{section.title}</h3>
    <SimpleMarkdown text={section.content} />
  </div>
);

const ResultsDashboard: React.FC<ResultsDashboardProps> = ({ data, onReset }) => {
  const [activeTab, setActiveTab] = useState<'main' | 'tech' | 'sales'>('main');

  const getScoreColor = (score: number) => {
    if (score >= 80) return '#4ade80';
    if (score >= 50) return '#facc15';
    return '#f87171';
  };

  /**
   * Safe text cleaner for jsPDF standard fonts.
   * Standard PDF fonts (Helvetica) don't support Polish UTF-8 chars without embedded TTF.
   * This ensures the text is READABLE and "amazing" instead of garbled.
   */
  const cleanText = (text: string): string => {
    const map: Record<string, string> = {
      'ą': 'a', 'ć': 'c', 'ę': 'e', 'ł': 'l', 'ń': 'n', 'ó': 'o', 'ś': 's', 'ź': 'z', 'ż': 'z',
      'Ą': 'A', 'Ć': 'C', 'Ę': 'E', 'Ł': 'L', 'Ń': 'N', 'Ó': 'O', 'Ś': 'S', 'Ź': 'Z', 'Ż': 'Z'
    };
    return text.replace(/[ąćęłńóśźżĄĆĘŁŃÓŚŹŻ]/g, m => map[m] || m).replace(/\*\*/g, '');
  };

  const generatePDF = (type: 'main' | 'tech' | 'sales') => {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    });

    const margin = 20;
    const pageWidth = 210;
    let y = 0;

    // Helper: Add a new page with header
    const addNewPage = () => {
      doc.addPage();
      drawHeader();
      y = 50;
    };

    const drawHeader = () => {
      doc.setFillColor(15, 23, 42); // Slate 900
      doc.rect(0, 0, pageWidth, 40, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(22);
      doc.text('GEO Audit Pro Agent', margin, 20);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(9);
      doc.text(cleanText(`Raport Wygenerowany: ${new Date().toLocaleDateString('pl-PL')}`), 140, 20);

      doc.setDrawColor(79, 70, 229); // Indigo 600
      doc.setLineWidth(1.5);
      doc.line(0, 40, pageWidth, 40);
    };

    const addText = (text: string, size: number = 10, isBold: boolean = false, color: [number, number, number] = [31, 41, 55], spacing: number = 5) => {
      doc.setFontSize(size);
      doc.setFont('helvetica', isBold ? 'bold' : 'normal');
      doc.setTextColor(color[0], color[1], color[2]);

      const lines = doc.splitTextToSize(cleanText(text), pageWidth - (margin * 2));

      lines.forEach((line: string) => {
        if (y > 275) addNewPage();
        doc.text(line, margin, y);
        y += (size * 0.4) + 2;
      });
      y += spacing;
    };

    const addSectionHeader = (title: string, color: [number, number, number] = [79, 70, 229]) => {
      if (y > 250) addNewPage();
      doc.setFillColor(color[0], color[1], color[2], 0.1);
      doc.rect(margin - 2, y - 6, pageWidth - (margin * 2) + 4, 10, 'F');
      addText(title.toUpperCase(), 12, true, color, 8);
    };

    // START GENERATION
    drawHeader();
    y = 55;

    const reportTitles = {
      main: 'STRATEGICZNY AUDYT WIDOCZNOSCI GEO',
      tech: 'AUDYT TECHNICZNY I STRUKTURA DANYCH',
      sales: 'GEO SALES TEASER - POTENCJAL BIZNESOWY'
    };

    // Hero Info
    addText(reportTitles[type], 18, true, [15, 23, 42], 10);
    addText(`DLA FIRMY: ${data.companyName}`, 13, true, [79, 70, 229], 5);
    addText(`WYNIK OGOLNY AI: ${data.overallScore}/100`, 11, true, [15, 23, 42], 12);

    if (type === 'main') {
      addSectionHeader('PODSUMOWANIE WYKONAWCZE');
      addText(data.executiveSummary, 10, false, [51, 65, 85], 10);

      data.mainReportSections.forEach(section => {
